const s=[{target:"#tesseract",title:"Your Hosting Catalog",icon:"fad fa-police-box",color:"#9d4edd",content:"This is your one-stop shop for picking a hosting plan. Think of each plan as a box — the bigger the box, the more power, storage, and tools you get.",placement:"right"},{target:"#tesseract-tour-nav",title:"Three Sizes to Pick From",icon:"fad fa-police-box",color:"#9d4edd",content:"Plans are organized into three tracks based on size:<br><br><strong>Micro</strong> — Perfect for personal sites and small projects.<br><strong>Macro</strong> — Built for growing businesses and agencies.<br><strong>Omni</strong> — Enterprise-grade, full sovereign infrastructure.",placement:"right"},{target:".tesseract-track-micro",title:"Browsing a Track",icon:"fad fa-police-box",color:"#9d4edd",content:"Each track expands to show its individual plans. Starting from the entry-level box at the top, each step up adds more tools and horsepower.",placement:"right",onEnter:()=>{const e=document.querySelector(".tesseract-track-micro");if(!e?.classList.contains("v-list-group--active")){const t=e?.querySelector(":scope > .v-list-group__header");t&&t.click()}}},{target:"#tesseract-tier-quantum",title:"Your First Box: Quantum",icon:"fad fa-police-box",color:"#9d4edd",content:"This is the starting plan. When you select a box, the background canvas comes alive to show you a feel for its speed and power.<br><br>Every box — even this one — comes fully loaded with a copy of <strong>YouMeOS</strong>, your own private operating system in the cloud.",placement:"right",onEnter:()=>{const e=document.querySelector(".tesseract-track-micro");if(!e?.classList.contains("v-list-group--active")){const o=e?.querySelector(":scope > .v-list-group__header");o&&o.click()}const t=document.querySelector("#tesseract-tier-quantum");t&&t.click()}},{target:()=>null,title:"Your Own Copy of YouMeOS",icon:"fad fa-police-box",color:"#9d4edd",content:"That means you get the same desktop, the same tools, and the same experience you're using right now — hosted on <em>your</em> hardware, under <em>your</em> control."}];export{s as tesseractTourSteps};
